require('should');

const zapier = require('zapier-platform-core');

const App = require('../index');
const appTester = zapier.createAppTester(App);

const nock = require('nock');

describe('creates', () => {

    it('should send a stream message', (done) => {

        const bundle = {
            authData: {
                api_key: 'secret',
                domain: 'https://yourzulipsubdomain.zulipchat.com/api/v1',
                username: 'zapierbot@zulip.com'
            },
            inputData: {
                stream: 2,
                topic: 'Sample topic',
                content: 'Sample content'
            }
        };

        const sample = {
            result: 'success',
            msg: '',
            id: 36,
            message_url: 'https://zulip.yourcompany.org/#narrow/stream/announce/topic/Announcement/near/36'
        };

        // mocks the next request that matches this url and querystring
        nock('https://yourzulipsubdomain.zulipchat.com')
            .post('/api/v1/messages')
            .reply(200, sample);

        appTester(App.creates.stream_message.operation.perform, bundle)
            .then((json_response) => {
                json_response.should.have.property('msg');
                json_response.result.should.eql('success');
                json_response.should.have.property('id');
                json_response.should.have.property('message_url');
                done();
            })
            .catch(done);

    });

    it('should send a stream message using a stream name', (done) => {

        const bundle = {
            authData: {
                api_key: 'secret',
                domain: 'https://yourzulipsubdomain.zulipchat.com/api/v1',
                username: 'zapierbot@zulip.com'
            },
            inputData: {
                stream: '#stream',
                topic: 'Sample topic',
                content: 'Sample content'
            }
        };

        const sample = {
            result: 'success',
            msg: '',
            id: 36,
            message_url: 'https://zulip.yourcompany.org/#narrow/stream/announce/topic/Announcement/near/36'
        };

        // mocks the next request that matches this url and querystring
        nock('https://yourzulipsubdomain.zulipchat.com')
            .post('/api/v1/messages')
            .reply(200, sample);

        appTester(App.creates.stream_message.operation.perform, bundle)
            .then((json_response) => {
                json_response.should.have.property('msg');
                json_response.result.should.eql('success');
                json_response.should.have.property('id');
                json_response.should.have.property('message_url');
                done();
            })
            .catch(done);

    });

    it('should send a private message', (done) => {
        const bundle = {
            authData: {
                api_key: 'secret',
                domain: 'https://yourzulipsubdomain.zulipchat.com/',
                username: 'zapierbot@zulip.com'
            },
            inputData: {
                recipients: [1, 3],
                content: 'Sample content'
            }
        };

        const sample = {
            result: 'success',
            msg: '',
            id: 36,
            message_url: 'https://yourzulipsubdomain.zulipchat.com/#narrow/id/36'
        };

        // mocks the next request that matches this url and querystring
        nock('https://yourzulipsubdomain.zulipchat.com')
            .post('/api/v1/messages')
            .reply(200, sample);

        appTester(App.creates.private_message.operation.perform, bundle)
            .then((json_response) => {
                json_response.should.have.property('msg');
                json_response.should.have.property('id');
                json_response.result.should.eql('success');
                json_response.should.have.property('message_url');
                done();
            })
            .catch(done);
    });
});

const authentication = require('./authentication');
const stream_message = require('./creates/stream_message');
const private_message = require('./creates/private_message');

const App = {
    // This is just shorthand to reference the installed dependencies
    // for the app. Zapier will need to know these before we can upload.
    version: require('./package.json').version,
    platformVersion: require('zapier-platform-core').version,

    authentication: authentication,

    beforeRequest: [
    ],

    afterResponse: [
    ],

    resources: {
    },

    // If you want your trigger to show up, you better include it here!
    triggers: {
    },

    // If you want your searches to show up, you better include it here!
    searches: {
    },

    // If you want your creates to show up, you better include it here!
    creates: {
        [stream_message.key]: stream_message,
        [private_message.key]: private_message
    }
};

// Finally, export the app.
module.exports = App;

const URL = require('url').URL;

const webhookBotErrorMessage = 'This API is not available to incoming webhook bots.';

const sanitizeZulipURL = (domain) => {
    if (!domain.match(/^[a-zA-Z]+:\/\//))
    {
        domain = 'https://' + domain;
    }
    const parsed_url = new URL(domain);
    return parsed_url.origin;
};

const constructStreamMessageURL = (data) => {
    let stream_info = data.stream;
    if (!isNaN(parseInt(stream_info, 10))) {
        stream_info = stream_info + '-';
    }
    const url = `${data.realm}/#narrow/stream/${stream_info}/topic/${data.topic}/near/${data.id}`;
    return encodeURI(url);
};

const constructPrivateMessageURL = (data) => {
    const url = `${data.realm}/#narrow/id/${data.id}`;
    return encodeURI(url);
};

module.exports = {
    'sanitizeZulipURL': sanitizeZulipURL,
    'webhookBotErrorMessage': webhookBotErrorMessage,
    'constructStreamMessageURL': constructStreamMessageURL,
    'constructPrivateMessageURL': constructPrivateMessageURL
};

const zulip = require('zulip-js');
const sanitize = require('../util.js').sanitizeZulipURL;
const webhookBotError = require('../util.js').webhookBotErrorMessage;

const getStreams = (z, bundle) => {
    const config = {
        realm: sanitize(bundle.authData.domain),
        username: bundle.authData.username,
        apiKey: [REDACTED]
    };

    return zulip(config).then((client) => {
        const params = {
            include_public: true,
            include_subscribed: true,
            include_owner_subscribed: true
        };
        return client.streams.retrieve(params).then((res) => {
            // If the requesting user can't authenticate because they are
            // an incoming webhook bot, we should simply return the response
            // so that getStreamField can handle it.
            if (res.result !== 'success' && res.msg === webhookBotError) {
                return res;
            }
            else if (res.result !== 'success' && res.msg !== webhookBotError) {
                throw new Error(res.msg);
            }

            var choices = {};
            res.streams.forEach((stream) => {
                choices[stream.stream_id] = stream.name;
            });

            const field = {
                key: 'stream',
                required: true,
                label: 'Stream',
                choices: choices,
            };

            return field;
        });
    });
};

const getStreamField = (z, bundle) => {
    const defaultField =  {
        key: 'stream',
        required: true,
        type: 'string',
        label: 'Stream name'
    };

    return getStreams(z, bundle).then((res) => {
        if (res.result !== 'success' && res.msg === webhookBotError) {
            return defaultField;
        }

        return res;
    });
};

module.exports = {
    'getStreamField': getStreamField
};

const zulip = require('zulip-js');
const sanitize = require('../util.js').sanitizeZulipURL;
const constructStreamMessageURL = require('../util.js').constructStreamMessageURL;
const getStreamField = require('./custom_fields.js').getStreamField;

module.exports = {
    key: 'stream_message',
    noun: 'Stream message',
    display: {
        label: 'Send a Stream Message',
        description: 'Send a message to a Zulip stream'
    },

    operation: {
        inputFields: [
            getStreamField,
            {
                key: 'topic',
                required: true,
                type: 'string',
                label: 'Topic'
            },
            {
                key: 'content',
                required: true,
                type: 'text',
                label: 'Message content'
            }
        ],

        perform: (z, bundle) => {
            let stream = bundle.inputData.stream;
            if (!isNaN(parseInt(stream, 10))) {
                stream = z.JSON.stringify([parseInt(stream, 10)]);
            }
            else if (stream.charAt(0) === '#')
            {
                stream = stream.substr(1);
            }

            const params = {
                type: 'stream',
                client: 'ZulipZapierApp',
                to: stream,
                content: bundle.inputData.content,
                topic: bundle.inputData.topic
            };

            const config = {
                realm: sanitize(bundle.authData.domain),
                username: bundle.authData.username,
                apiKey: [REDACTED]
            };

            return zulip(config).then((client) => {
                return client.messages.send(params).then((response) => {
                    if (response.result !== 'success') {
                        throw new Error(response.msg);
                    }

                    const data = {
                        realm: config.realm,
                        stream: bundle.inputData.stream,
                        topic: bundle.inputData.topic,
                        id: response.id
                    };
                    response.message_url = constructStreamMessageURL(data);

                    return response;
                });
            });
        },

        // In cases where Zapier needs to show an example record to the user,
        // but we are unable to get a live example from the API, Zapier will
        // fallback to this hard-coded sample.
        sample: {
            result: 'success',
            msg: '',
            id: 36,
            message_url: 'https://zulip.yourcompany.org/#narrow/stream/announce/topic/Announcement/near/36'
        },
    }
};

const zulip = require('zulip-js');
const sanitize = require('../util.js').sanitizeZulipURL;
const constructPrivateMessageURL = require('../util.js').constructPrivateMessageURL;

module.exports = {
    key: 'private_message',

    noun: 'Private message',
    display: {
        label: 'Send a Private Message',
        description: 'Send a private or group message'
    },

    operation: {
        inputFields: [
            {
                key: 'recipients',
                required: true,
                type: 'string',
                label: 'Recipient(s)',
                helpText: 'Email addresses of recipients.',
                list: true
            },
            {
                key: 'content',
                required: true,
                type: 'text',
                label: 'Message content',
            }
        ],

        perform: (z, bundle) => {
            const userIDs = [];
            bundle.inputData.recipients.forEach((id) => {
                if (!isNaN(parseInt(id))) {
                    userIDs.push(parseInt(id));
                }
                else {
                    userIDs.push(id);
                }
            });

            const params = {
                type: 'private',
                client: 'ZulipZapierApp',
                to: z.JSON.stringify(userIDs),
                content: bundle.inputData.content
            };

            const config = {
                realm: sanitize(bundle.authData.domain),
                username: bundle.authData.username,
                apiKey: [REDACTED]
            };

            return zulip(config).then((client) => {
                return client.messages.send(params).then((response) => {
                    if (response.result !== 'success') {
                        throw new Error(response.msg);
                    }

                    const data = {
                        realm: config.realm,
                        id: response.id
                    };
                    response.message_url = constructPrivateMessageURL(data);

                    return response;
                });
            });
        },

        // In cases where Zapier needs to show an example record to the user,
        // but we are unable to get a live example from the API, Zapier will
        // fallback to this hard-coded sample.
        sample: {
            result: 'success',
            msg: '',
            id: 36,
            message_url: 'https://yourzulipsubdomain.zulipchat.com/#narrow/id/36'
        },
    }
};
